  [Semiring R] [AddCommGroup M] [AddCommGroup N] [AddCommGroup P] [Module R M] [Module R N] [Module R P] {f : M →ₗ[R] N}
  {g : N →ₗ[R] P} (h : Exact ⇑f ⇑g) (hf : Injective ⇑f) :
  { l // g ∘ₗ l = LinearMap.id } ≃ { e // f = ↑e.symm ∘ₗ inl R M P ∧ g = snd R M P ∘ₗ ↑e }
